solutions.naive:
class Solution:
    def asteroidCollision(self, asteroids: list[int]) -> list[int]:
        arr = asteroids[:]
        changed = True
        while changed:
            changed = False
            i = 0
            while i + 1 < len(arr):
                if arr[i] > 0 and arr[i + 1] < 0:
                    left, right = abs(arr[i]), abs(arr[i + 1])
                    if left == right:
                        arr[i:i + 2] = []
                    elif left > right:
                        arr.pop(i + 1)
                    else:
                        arr.pop(i)
                    changed = True
                    break
                i += 1
        return arr

solutions.better:
class Solution:
    def asteroidCollision(self, asteroids: list[int]) -> list[int]:
        stack = []
        for a in asteroids:
            alive = True
            while alive and a < 0 and stack and stack[-1] > 0:
                if stack[-1] < -a:
                    stack.pop()
                    continue
                if stack[-1] == -a:
                    stack.pop()
                alive = False
            if alive:
                stack.append(a)
        return stack

solutions.optimal:
class Solution:
    def asteroidCollision(self, asteroids: list[int]) -> list[int]:
        stack = []
        for a in asteroids:
            while stack and a < 0 < stack[-1]:
                if stack[-1] < -a:
                    stack.pop()
                    continue
                if stack[-1] == -a:
                    stack.pop()
                break
            else:
                # Runs when the asteroid was not destroyed by a break.
                stack.append(a)
        return stack

